// Step 1: Get the raw string from OpenAI
let raw = $json.output || "";

// Step 2: Parse the string inside "output"
let parsed;
try {
  parsed = JSON.parse(raw);   // this turns it into a real array
} catch (e) {
  throw new Error("Could not parse OpenAI output: " + raw);
}

// Step 3: Return as n8n items
return parsed.map(item => ({ json: item }));
